import { createPlayerError } from "../../core/errors.js";

/** A scheduled ad break. */
export interface AdBreak {
  readonly id: string;
  readonly time: number;
  readonly duration: number;
  readonly label?: string;
}

/** An ad schedule. */
export interface AdSchedule {
  readonly breaks: readonly AdBreak[];
  readonly preRoll?: boolean;
  readonly postRoll?: boolean;
}

/** Controls ad playback. Implementations are supplied by an ad SDK. */
export interface AdController {
  readonly schedule: AdSchedule;
  playPreRoll(): Promise<void>;
  playMidRoll(breakId: string): Promise<void>;
  playPostRoll(): Promise<void>;
  destroy(): void;
}

/** Finds the ad break covering a timestamp. */
export function findAdBreakAt(schedule: AdSchedule, time: number): AdBreak | null {
  for (const adBreak of schedule.breaks) {
    if (time >= adBreak.time && time < adBreak.time + adBreak.duration) {
      return adBreak;
    }
  }

  return null;
}

/**
 * Creates a placeholder ad controller.
 *
 * The skeleton reserves the contract; wire a VAST/IMA SDK by replacing the
 * three `play*` methods.
 */
export function createAdController(schedule: AdSchedule): AdController {
  const notConfigured = (): never => {
    throw createPlayerError("Ad playback requires an ad SDK adapter.", {
      code: "not-implemented",
    });
  };

  return {
    schedule,
    async playPreRoll(): Promise<void> {
      if (schedule.preRoll === true) {
        notConfigured();
      }
    },
    async playMidRoll(breakId: string): Promise<void> {
      if (schedule.breaks.some((adBreak) => adBreak.id === breakId)) {
        notConfigured();
      }
    },
    async playPostRoll(): Promise<void> {
      if (schedule.postRoll === true) {
        notConfigured();
      }
    },
    destroy(): void {
      // Nothing to release until an SDK adapter is attached.
    },
  };
}
